<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Support\Str;
class LayawayPlan extends Model { protected $fillable=['business_id','branch_id','customer_id','plan_number','target_amount','paid_amount','collection_due_date','status','notes','created_by','completed_at']; protected static function booted(): void { static::creating(fn(self $m)=>$m->public_id??=(string)Str::uuid()); } protected function casts(): array{return ['target_amount'=>'decimal:2','paid_amount'=>'decimal:2','collection_due_date'=>'date','completed_at'=>'datetime'];} public function getRouteKeyName(): string{return 'public_id';} public function customer():BelongsTo{return $this->belongsTo(Customer::class);} public function payments():HasMany{return $this->hasMany(LayawayPayment::class);} public function items():HasMany{return $this->hasMany(LayawayItem::class);} }
